int32 err;

err = OS_TaskCreate(NULL,                   /* Error.*/
                    "failing task",
                    test_task1,
                    (uint32 *)wa_test1,
                    sizeof wa_test1,
                    TASKS_BASE_PRIORITY,
                    0);
test_assert(err == OS_INVALID_POINTER, "NULL not detected");
test_assert_sequence("", "task executed");

int32 err;
uint32 tid;

err = OS_TaskCreate(&tid,
                    NULL,                   /* Error.*/
                    test_task1,
                    (uint32 *)wa_test1,
                    sizeof wa_test1,
                    TASKS_BASE_PRIORITY,
                    0);
test_assert(err == OS_INVALID_POINTER, "NULL not detected");
test_assert_sequence("", "task executed");

int32 err;
uint32 tid;

err = OS_TaskCreate(&tid,
                    "failing task",
                    test_task1,
                    (uint32 *)NULL,         /* Error.*/
                    sizeof wa_test1,
                    TASKS_BASE_PRIORITY,
                    0);
test_assert(err == OS_INVALID_POINTER, "NULL not detected");
test_assert_sequence("", "task executed");

int32 err;
uint32 tid;

err = OS_TaskCreate(&tid,
                    "this is a very very long task name", /* Error.*/
                    test_task1,
                    (uint32 *)wa_test1,
                    sizeof wa_test1,
                    TASKS_BASE_PRIORITY,
                    0);
test_assert(err == OS_ERR_NAME_TOO_LONG, "name limit not detected");
test_assert_sequence("", "task executed");

int32 err;
uint32 tid;

err = OS_TaskCreate(&tid,
                    "failing task",
                    test_task1,
                    (uint32 *)wa_test1,
                    sizeof wa_test1,
                    0,                      /* Error.*/
                    0);
test_assert(err == OS_ERR_INVALID_PRIORITY, "priority error not detected");
test_assert_sequence("", "task executed");

err = OS_TaskCreate(&tid,
                   "failing task",
                   test_task1,
                   (uint32 *)wa_test1,
                   sizeof wa_test1,
                   256,                     /* Error.*/
                   0);
test_assert(err == OS_ERR_INVALID_PRIORITY, "priority error not detected");
test_assert_sequence("", "task executed");

int32 err;
uint32 tid;

err = OS_TaskCreate(&tid,
                    "failing task",
                    test_task1,
                    (uint32 *)wa_test1,
                    16,                     /* Error.*/
                    TASKS_BASE_PRIORITY,
                    0);
test_assert(err == OS_INVALID_INT_NUM, "stack insufficient size not detected");
test_assert_sequence("", "task executed");

int32 err;
uint32 tid;

err = OS_TaskCreate(&tid,
                    "running task",
                    test_task1,
                    (uint32 *)wa_test1,
                    sizeof wa_test1,
                    TASKS_BASE_PRIORITY,
                    0);
test_assert(err == OS_SUCCESS, "task creation failed");

err = OS_TaskCreate(&tid,
                    "running task",
                    test_task2,
                    (uint32 *)wa_test2,
                    sizeof wa_test2,
                    TASKS_BASE_PRIORITY,
                    0);
test_assert(err == OS_ERR_NAME_TAKEN, "name conflict not detected");

err = OS_TaskCreate(&tid,
                    "conflicting task",
                    test_task1,
                    (uint32 *)wa_test1,
                    sizeof wa_test1,
                    TASKS_BASE_PRIORITY,
                    0);
test_assert(err == OS_ERR_NO_FREE_IDS, "stack conflict not detected");

err = OS_TaskWait(tid);
test_assert(err == OS_SUCCESS, "wait failed");
test_assert_sequence("A", "task not executed");

err = OS_TaskCreate(&tid,
                    "running task",
                    test_task1,
                    (uint32 *)wa_test1,
                    sizeof wa_test1,
                    TASKS_BASE_PRIORITY,
                    0);
test_assert(err == OS_SUCCESS, "task creation failed");

err = OS_TaskWait(tid);
test_assert(err == OS_SUCCESS, "wait failed");
test_assert_sequence("A", "task not executed");

int32 err; uint32 tid1, tid2, tid3, tid4;
err = OS_TaskCreate(&tid4, "running task 4", test_task4, (uint32 *)wa_test4, sizeof wa_test4, TASKS_BASE_PRIORITY - 0, 0); test_assert(err == OS_SUCCESS, "task 4 creation failed");
err = OS_TaskCreate(&tid3, "running task 3", test_task3, (uint32 *)wa_test3, sizeof wa_test3, TASKS_BASE_PRIORITY - 1, 0); test_assert(err == OS_SUCCESS, "task 3 creation failed");
err = OS_TaskCreate(&tid2, "running task 2", test_task2, (uint32 *)wa_test2, sizeof wa_test2, TASKS_BASE_PRIORITY - 2, 0); test_assert(err == OS_SUCCESS, "task 2 creation failed");
err = OS_TaskCreate(&tid1, "running task 1", test_task1, (uint32 *)wa_test1, sizeof wa_test1, TASKS_BASE_PRIORITY - 3, 0); test_assert(err == OS_SUCCESS, "task 1 creation failed");

int32 err; uint32 tid1, tid2, tid3, tid4;
err = OS_TaskCreate(&tid1, "running task 1", test_task1, (uint32 *)wa_test1, sizeof wa_test1, TASKS_BASE_PRIORITY - 3, 0); test_assert(err == OS_SUCCESS, "task 1 creation failed");
err = OS_TaskCreate(&tid2, "running task 2", test_task2, (uint32 *)wa_test2, sizeof wa_test2, TASKS_BASE_PRIORITY - 2, 0); test_assert(err == OS_SUCCESS, "task 2 creation failed");
err = OS_TaskCreate(&tid3, "running task 3", test_task3, (uint32 *)wa_test3, sizeof wa_test3, TASKS_BASE_PRIORITY - 1, 0); test_assert(err == OS_SUCCESS, "task 3 creation failed");
err = OS_TaskCreate(&tid4, "running task 4", test_task4, (uint32 *)wa_test4, sizeof wa_test4, TASKS_BASE_PRIORITY - 0, 0); test_assert(err == OS_SUCCESS, "task 4 creation failed");

int32 err; uint32 tid1, tid2, tid3, tid4;
err = OS_TaskCreate(&tid2, "running task 2", test_task2, (uint32 *)wa_test2, sizeof wa_test2, TASKS_BASE_PRIORITY - 2, 0); test_assert(err == OS_SUCCESS, "task 2 creation failed");
err = OS_TaskCreate(&tid1, "running task 1", test_task1, (uint32 *)wa_test1, sizeof wa_test1, TASKS_BASE_PRIORITY - 3, 0); test_assert(err == OS_SUCCESS, "task 1 creation failed");
err = OS_TaskCreate(&tid4, "running task 4", test_task4, (uint32 *)wa_test4, sizeof wa_test4, TASKS_BASE_PRIORITY - 0, 0); test_assert(err == OS_SUCCESS, "task 4 creation failed");
err = OS_TaskCreate(&tid3, "running task 3", test_task3, (uint32 *)wa_test3, sizeof wa_test3, TASKS_BASE_PRIORITY - 1, 0); test_assert(err == OS_SUCCESS, "task 3 creation failed");

int32 err;

err = OS_TaskDelete((uint32)-1);
test_assert(err == OS_ERR_INVALID_ID, "wrong task id not detected");

int32 err;

err = OS_TaskCreate(&tid,
                    "deletable task",
                    test_task_delete,
                    (uint32 *)wa_test1,
                    sizeof wa_test1,
                    TASKS_BASE_PRIORITY,
                    0);
test_assert(err == OS_SUCCESS, "deletable task creation failed");

int32 err;

(void) OS_TaskDelay(50);
err = OS_TaskDelete(tid);
test_assert(err == OS_SUCCESS, "delete failed");
test_assert_sequence("ABC", "events order violation");

int32 err;

err = OS_TaskSetPriority((uint32)-1, 0);
test_assert(err == OS_ERR_INVALID_PRIORITY, "low priority accepted");
err = OS_TaskSetPriority((uint32)-1, 256);
test_assert(err == OS_ERR_INVALID_PRIORITY, "high priority accepted");
err = OS_TaskSetPriority((uint32)-1, 128);
test_assert(err == OS_ERR_INVALID_ID, "invalid target accepted");

int32 err;

err = OS_TaskCreate(&priority_tid,
                    "priority target",
                    test_task_priority,
                    (uint32 *)wa_test1,
                    sizeof wa_test1,
                    TASKS_BASE_PRIORITY,
                    0);
test_assert(err == OS_SUCCESS, "task creation failed");

err = OS_TaskSetPriority(priority_tid, 128);
test_assert(err == OS_SUCCESS, "priority change failed");

int32 err;
OS_task_prop_t info;

err = OS_TaskGetInfo(priority_tid, &info);
test_assert(err == OS_SUCCESS, "task info failed");
test_assert(info.priority == 128, "priority conversion failed");

err = OS_TaskDelete(priority_tid);
test_assert(err == OS_SUCCESS, "task deletion failed");
priority_tid = 0;

