err = OS_TimerCreate(NULL,                      /* Error.*/
                     "failing timer",
                     &accuracy,
                     tmr_callback);
test_assert(err == OS_INVALID_POINTER, "NULL not detected");

int32 err;
uint32 tmid;
uint32 accuracy;

err = OS_TimerCreate(&tmid,
                     NULL,                      /* Error.*/
                     &accuracy,
                     tmr_callback);
test_assert(err == OS_INVALID_POINTER, "NULL not detected");

